import json


def execute(node_id, node_data, context):
    """Preserve native list pagination and normalize public reader data.

    Args:
        node_id: The current node identifier.
        node_data: The script node configuration.
        context: The workflow state containing the response envelope.

    Raises:
        ValueError: If the API fails, changes shape, or requires chapter access.
    """
    if context.get("status") != 200:
        raise ValueError("轻之国度：HTTP 请求失败")
    envelope = json.loads(context["response"])
    if envelope.get("code") != 0 or not isinstance(envelope.get("data"), dict):
        raise ValueError("轻之国度：接口返回错误 " + str(envelope.get("code")))
    data = envelope["data"]
    if context.get("$start") == "search_start":
        items = [
            {
                "id": str(item["book_id"]),
                "title": item["title"],
                "cover": item.get("cover_url", ""),
                "rating": item.get("rating_score_10")
                if item.get("rating_displayable")
                else None,
                "uploader": item.get("author_name", ""),
                "category": " / ".join(
                    item.get("visible_tags") or item.get("tags") or []
                ),
                "uploaded_at": item.get("updated_at", ""),
                "misc": item.get("summary_short", ""),
            }
            for item in data["list"]
        ]
        context["result"] = {
            "items": items,
            "totalPages": max(1, int(data["pagination"]["page_count"])),
        }
        return
    if node_id == "ln-chapter-result":
        if str(data.get("locked", 0)).lower() in ("1", "true"):
            raise ValueError("轻之国度：本章节需要登录或解锁，请在原站阅读")
        snapshot = data.get("body_snapshot") or {}
        content = snapshot.get("body_text") or snapshot.get("selection_text")
        if not content:
            raise ValueError("轻之国度：章节正文为空")
        context["result"] = {
            "id": str(data["book_id"]),
            "title": data["book_title"] + " · " + data["title"],
            "media_type": "text",
            "text": [line.strip() for line in content.splitlines() if line.strip()],
            "chapters": context["catalog"]["chapters"],
        }
        return
    request = context["catalog_request"]
    requests = list(context["catalog_requests"])
    page_count = int(data["pagination"]["page_count"])
    if request["page"] == 1:
        requests.extend({**request, "page": page} for page in range(2, page_count + 1))
    if request["kind"] == "volumes":
        context["book_title"] = data["title"]
        requests.extend(
            {
                "kind": "chapters",
                "page": 1,
                "volume_id": str(volume["volume_id"]),
                "volume_title": volume["title"],
                "volume_order": (request["page"] - 1) * 50 + index,
            }
            for index, volume in enumerate(data["list"])
        )
    else:
        chapters = list(context["catalog_items"])
        chapters.extend(
            {
                "id": str(chapter["chapter_id"]),
                "title": request["volume_title"] + " · " + chapter["title"],
                "_order": [
                    request["volume_order"],
                    int(
                        chapter.get("chapter_no")
                        or ((request["page"] - 1) * 50 + index)
                    ),
                ],
            }
            for index, chapter in enumerate(data["list"])
        )
        context["catalog_items"] = chapters
    context["catalog_requests"] = requests

